// Static UI assets: RGB565 images in flash (memory-mapped PROGMEM), generated by scripts/gen_assets.py
// from assets/*.png. Implemented in the generated src/assets_gen.cpp. No animation: every image is drawn
// once per screen change; the splash is drawn row by row so no full-screen buffer is needed.
#pragma once

#include <cstdint>

namespace oyster::assets {

enum class IconId : uint8_t {
  // module tiles (Home)
  Security, OysterAi, Linux, ControlDeck, SmartHome, Apps, Settings,
  // feature icons
  Wifi, Ble, Findings, Targets, Assess,
  // red-team tile (procedural red skull)
  RedTeam,
  // scratchpad tile (procedural calculator, no source art)
  Scratchpad,
  Count
};

constexpr uint16_t kIconSize = 24;        // square
constexpr uint16_t kTransparent = 0xF81F; // magenta key: skip these pixels when drawing

struct Image {
  uint16_t w;
  uint16_t h;
  const uint16_t* px;  // w*h RGB565, row-major, in flash
};

const Image& icon(IconId id);  // kIconSize x kIconSize
const Image& logo();           // 48 x 48 mascot
const Image& splash();         // 240 x 135 boot screen (includes frame 0 of the loader at its position)

// Short looping "loading" animation of the mascot. Frames are opaque (the splash background behind the
// mascot is baked in), stored back to back in flash, and drawn over the splash at (x, y): no RAM
// buffer, no alpha blending. Intended for the boot splash and busy screens only, at a low frame rate.
struct Animation {
  uint16_t w;
  uint16_t h;
  uint16_t x;       // top-left on the 240x135 splash
  uint16_t y;
  uint8_t frames;   // frame count (frame i starts at px + i * w * h)
  uint8_t fps;      // intended playback rate; keep it low
  const uint16_t* px;
};
const Animation& loader();

}  // namespace oyster::assets
